-- --- Varalakshmi Ksheera Arghyam ----------------------------------------------
update public.pooja_steps set
  instruction_en = 'Mix a little water into raw milk. Take the milk in the uddharani, recite the verse, then pour three times as the refrain says "idam arghyam" three times. Half a glass of raw milk is kept aside for this at the start, which is why it is on the samagri list.',
  instruction_ta = 'பச்சைப் பாலில் சிறிது ஜலம் கலக்கவும். உத்தரிணியில் பாலை எடுத்து, ஸ்லோகத்தைச் சொல்லி, "இதமர்க்யம்" என மூன்று முறை சொல்லும்போது மூன்று முறை விடவும். இதற்காகவே அரை டம்ளர் பச்சைப் பால் தொடக்கத்திலேயே தனியாக வைக்கப்படுகிறது; அதனால்தான் அது சாமக்ரி பட்டியலில் உள்ளது.',
  mantra_sanskrit = null,
  mantra_tamil = null,
  mantra_translit = null,
  meaning_en = 'Clean water in a vessel, mixed with sandal and flowers: I shall give you this arghyam, goddess; receive it, you who are dear to Hari. At the close it is given in milk.',
  source_ref = 'Arghyam verse from StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs; the kalpam gives it once, as an upachara, while the video gives it again in milk at the close. Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 1:05:34. The threefold idam-arghyam refrain follows the form the same publisher prints for a repeated arghyam.',
  updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam';

delete from public.archana_items where pooja_step_id in (select id from public.pooja_steps where (pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam'));
insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
