  ((select id from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam'), 1, 'शुद्धोदकं च पात्रस्थं गंध पुष्पादि मिश्रितं । अर्घ्यं दास्यामि ते देवी गृह्यतां हरिवल्लभे ॥
श्री वरलक्ष्मी देवतायै नमः इदमर्घ्यं इदमर्घ्यं इदमर्घ्यम् ।', 'ஶுத்தோதகம் ச பாத்ரஸ்தம் கம்த புஷ்பாதி மிஶ்ரிதம் । அர்க்யம் தாஸ்யாமி தே தேவீ க்ருஹ்யதாம் ஹரிவல்லபே ॥
ஶ்ரீ வரலக்ஷ்மீ தேவதாயை நம꞉ இதமர்க்யம் இதமர்க்யம் இதமர்க்யம் ।', 'śuddhodakaṃ ca pātrasthaṃ gaṃdha puṣpādi miśritaṃ । arghyaṃ dāsyāmi te devī gṛhyatāṃ harivallabhe ॥
śrī varalakṣmī devatāyai namaḥ idamarghyaṃ idamarghyaṃ idamarghyam ।',
   'श्री वरलक्ष्मी देवतायै नमः इदमर्घ्यं इदमर्घ्यं इदमर्घ्यम् ।', 'Pour the arghyam three times', 'மூன்று முறை அர்க்யம் விடவும்', 'Clean water in a vessel, mixed with sandal and flowers: I shall give you this arghyam, goddess; receive it, you who are dear to Hari.');

-- --- Varalakshmi Sharadu Dharanam ---------------------------------------------
update public.pooja_steps set
  instruction_en = 'The husband ties the saradu on his wife’s right wrist, making three knots, while the shloka is recited. These three are the knots of the tying itself and are not the nine granthis of the thread, which were just worshipped. Where there is no husband to tie it, an elder woman of the house ties it, or she ties it on herself, which is what the mantra literally says. It stays on until it wears through, or until next year’s vratham.',
  instruction_ta = 'கணவர் மனைவியின் வலது மணிக்கட்டில் சரட்டைக் கட்ட வேண்டும், மூன்று முடிச்சுகள் போட்டு, ஸ்லோகம் சொல்லியபடி. இந்த மூன்று முடிச்சுகள் கட்டுவதற்குரியவை; சற்று முன் பூஜிக்கப்பட்ட சரட்டின் ஒன்பது முடிச்சுகள் வேறு. கட்ட கணவர் இல்லையெனில் வீட்டின் மூத்த பெண் கட்டுவார்; அல்லது தானே கட்டிக்கொள்ளலாம் — மந்திரம் சொல்வதும் அதுவே. அறுந்து போகும் வரை, அல்லது அடுத்த வருட விரதம் வரை, அது கையிலேயே இருக்கும்.',
  philosophy_en = 'Badhnami dakshine haste, "I tie it on the right hand". The verb is first person, because a vidhi text is written for whoever is reciting it; it is not a ruling that the tying must be done alone. In most Tamil households the husband ties it, with three knots, and the older women tie it for the girls. Nine knots were worshipped a moment ago and three are made now, and the two counts belong to different things: the nine are the thread, the three are the tying.',
  source_ref = 'Mantra from StotraNidhi Sri Varalakshmi Vrata Kalpam (Telugu), round-trip verified by scripts/parse-varalakshmi-kalpam.mjs (tora bandhana mantram); Sathya Vadyar, Varalakshmi Poojai 2026 step by step, chapter at 59:38. The husband tying it with three knots is Tamil household practice, reported by this project’s owner and NOT stated in the kalpam, which gives the verb in the first person only; flagged for practitioner review.',
  updated_at = now()
where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam';

-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.archana_items where pooja_step_id in (select id from public.pooja_steps where (pooja_id = 'ganesha_standard' and step_title_en = 'Ksheera Arghyam'));
  if n <> 4 then raise exception 'ganesha arghyam has % offerings, expected 4', n; end if;
  select count(*) into n from public.archana_items where pooja_step_id in (select id from public.pooja_steps where (pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam'));
  if n <> 1 then raise exception 'varalakshmi arghyam has % offerings, expected 1', n; end if;
  -- Every arghyam line must carry its pouring refrain, or the count is lost.
  select count(*) into n from public.archana_items
   where pooja_step_id in (select id from public.pooja_steps where (pooja_id = 'ganesha_standard' and step_title_en = 'Ksheera Arghyam') or (pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam'))
     and (offering_deva is null or offering_deva not like '%इदमर्घ्य%');
  if n > 0 then raise exception '% arghyam lines have no idam-arghyam refrain', n; end if;
  -- The blob the verses came out of must be gone, or both would show.
  select count(*) into n from public.pooja_steps
   where ((pooja_id = 'ganesha_standard' and step_title_en = 'Ksheera Arghyam') or (pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam')) and mantra_sanskrit is not null;
  if n > 0 then raise exception '% arghyam steps still hold a step mantra', n; end if;
  select count(*) into n from public.pooja_steps
   where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam' and instruction_en like '%three knots%';
  if n <> 1 then raise exception 'sharadu dharanam does not mention the three knots'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;

